namespace Lokad.Awk.Tests;

internal static partial class AwkGoldenCorpus
{
    // GNU 5.2/5.4 C.UTF-8/UTC controls select the modern reference. CRLF input
    // and case-sensitive Unicode literal FS use the documented Lokad policies.
    // Blank-only GNU getline EOF/RT is a separate pending finding.
    private static IEnumerable<AwkGoldenCase> RangeParagraphCompatibilityCases()
    {
        foreach (var row in RangeParagraphRows)
            yield return AwkGoldenCaseBuilder.Create(row.Name, row.Arguments, row.Files)
                .WithStandardInput(row.Input).WithStdOut(row.Output).Build();
    }

    private sealed record RangeParagraphRow(string Name, string[] Arguments,
